mapper.select:
select r.resource_id, r.author_id, u.nick_name as author_nickname, r.resource_type, r.resource_category_id, c.category_name as category_name, r.title, r.summary, r.link_url, r.link_icon, r.file_object_id, f.original_name as original_name, f.content_length as content_length, f.content_type as content_type, r.publish_time, r.view_count, r.download_count, (select count(*) from resource_like rl where rl.resource_id = r.resource_id) as like_count, (select count(*) from resource_collect rc where rc.resource_id = r.resource_id) as collect_count, (select coalesce(round(avg(rating.score), 2), 0) from resource_rating rating where rating.resource_id = r.resource_id) as rating_avg, (select count(*) from resource_rating rating where rating.resource_id = r.resource_id) as rating_count from resource r left join sys_user u on r.author_id = u.user_id left join resource_category c on r.resource_category_id = c.category_id and c.deleted = 0 left join file_object f on r.file_object_id = f.object_id and f.deleted = 0 where
and MATCH(r.title, r.summary, r.description) AGAINST(#{keyword} IN BOOLEAN MODE)
and r.resource_type = #{resourceType}
and r.resource_category_id in #{rcid}
and r.resource_category_id = #{resourceCategoryId}
order by r.publish_time desc, r.resource_id desc
order by MATCH(r.title, r.summary, r.description) AGAINST(#{keyword} IN NATURAL LANGUAGE MODE) desc, r.publish_time desc, r.resource_id desc
order by r.publish_time desc, r.resource_id desc
order by (r.download_count * 3 + r.view_count + (select count(*) from resource_like rl where rl.resource_id = r.resource_id) * 2 + (select count(*) from resource_collect rc where rc.resource_id = r.resource_id) * 2) desc, r.publish_time desc, r.resource_id desc

select r.resource_id, r.author_id, u.nick_name as author_nickname, r.resource_type, r.resource_category_id, c.category_name as category_name, r.title, r.summary, r.link_url, r.link_icon, r.file_object_id, f.original_name as original_name, f.content_length as content_length, f.content_type as content_type, r.publish_time, r.view_count, r.download_count, (select count(*) from resource_like rl where rl.resource_id = r.resource_id) as like_count, (select count(*) from resource_collect rc where rc.resource_id = r.resource_id) as collect_count, (select coalesce(round(avg(rating.score), 2), 0) from resource_rating rating where rating.resource_id = r.resource_id) as rating_avg, (select count(*) from resource_rating rating where rating.resource_id = r.resource_id) as rating_count from resource r left join sys_user u on r.author_id = u.user_id left join resource_category c on r.resource_category_id = c.category_id and c.deleted = 0 left join file_object f on r.file_object_id = f.object_id and f.deleted = 0 where and r.resource_id <> #{excludeResourceId}
and r.resource_id not in #{eid}
order by (r.download_count * 3 + r.view_count + (select count(*) from resource_like rl where rl.resource_id = r.resource_id) * 2 + (select count(*) from resource_collect rc where rc.resource_id = r.resource_id) * 2) desc, r.publish_time desc, r.resource_id desc limit #{size}
